    mutationFn: cancelBooking,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['myBookings'] });
      queryClient.invalidateQueries({ queryKey: ['gymClasses'] });
    },
  });
  return { mutate, mutateAsync, isPending, isError, error };
}

